/** The move a hand card dropped on one of its owner's zones stands for, or null. */
function txDropMove(s, seat, inst, key) {
    if (s.win >= 0 || s.who !== seat || !key || key === "hand")
        return null;
    const map = cellMapOf(s, seat);
    const mine = legalMoves(s).filter((m) => m.r >= 0 && map.instOf[m.r] === inst);
    if (mine.length === 0)
        return null;
    const want = [];
    if (key === "a0" || key === "a1" || key === "a2")
        want.push(A_DEPLOY0 + Number(key.charAt(1)));
    // The Location space of an arena: complete a Location there (a unit dropped on it deploys to that arena).
    if (key === "loc0" || key === "loc1" || key === "loc2")
        want.push(A_DEPLOY0 + Number(key.charAt(3)));
    if (key === "build") {
        want.push(A_BUILD);
        if (s.ph !== "setup")
            want.push(A_DEPLOY_BZ);
    }
    if (key === "res" && s.ph === "setup")
        want.push(A_DEPLOY_BZ);
    for (const a of want) {
        const m = mine.find((x) => x.a === a);
        if (m)
            return m;
    }
    // Something with one obvious play (an Event, a Battle card) can be dropped anywhere of yours.
    if (key !== "res" && mine.length === 1 && (s.ph === "event" || (mine[0].a >= A_ACT0 && mine[0].a < A_ACT0 + 4)))
        return mine[0];
    return null;
}
/** Why a hand card dropped on `key` was not played: the closest thing to a reason the player can act on. */
function txDropRefusal(s, inst, key) {
    if (!key)
        return "Drop it on an arena, a Location space or your build zone.";
    const d = defOf(s, inst);
    const isLoc = (d.ty & T_LOCATION) !== 0;
    const ar = key.indexOf("loc") === 0 ? Number(key.charAt(3)) : key.charAt(0) === "a" ? Number(key.charAt(1)) : -1;
    if (isLoc && ar >= 0 && arenasFor(d).indexOf(ar) < 0)
        return d.n + " is not a " + ARENA_NAMES[ar] + " Location.";
    if (ar >= 0 && s.ph === "build") {
        const cost = completeCostAt(s, inst, ar);
        if (cost > s.P[card(s, inst).o].bp)
            return d.n + " needs " + cost + " build points there (you have " + s.P[card(s, inst).o].bp + "). Drop it on your build zone to build it.";
    }
