    if (c.fd || (c.z === "hand" && c.o !== viewer))
        return;
    const d = defOf(s, inst);
    const who = txPractice ? { allow: ["spectators"] } : { audience: { scope: "seats", seats: [seatId] } };
    const w = txSpotWidget(s, "swtcg-look-" + seatId, "Cost " + (d.costX ? "X" : String(d.cost)), inst, who);
