            return;
        // The host checked the presser is in the widget's audience; still, only the deciding seat moves.
        if (!txPractice && seatId !== txSeats[s.who])
            return;
        if (wid === TX_DECIDE && id === "mu-aside") {
            // The mulligan's picks: each card set aside (one kernel move each), then the discard-or-shuffle choice.
            const picks = Array.isArray(event.value) ? event.value : [];
            const moves = picks.map((p) => txDecideMoves[String(p)]).filter((x) => !!x && x.r >= 0);
