        const at = txState;
        if (txRollReq !== req)
            return;
        if (!at || at.ph !== "roll" || at.who !== seat || txMoves.length !== key) {
            txRollReq = null;
            return;
        }
        const faces = await txRequestDice(at, seat, txDiceLeft(at), false);
        void txRun(async () => {
            const now = txState;
            if (!now || now.ph !== "roll" || now.who !== seat || txMoves.length !== key)
                return;
            txRollReq = null;
            txHumanMoved = true;
