// ============================================================================================
// Star Wars TCG - Force and Build counters for the Standard (hand-played) variant.
//
// Attached to the Play Mat in the base scene. Each seat gets two controls in the strip between
// its hand and its build zone, where the Force track used to be: Force on the player's left,
// Build on the player's right, each a "-" button, the total, and a "+" button. Anyone may press
// them, as anyone could move the old Force pawns (a seat restriction would also lock out a solo or
// preview table, whose player holds no live seat). The totals have no ceiling (the old track
// stopped at 14) and are kept in saved data, so a reload or a host change keeps them.
//
// The Scripted variant does not run this: its rules script shows the kernel's Force and Build in
// the same place with the same label ids, and the kernel owns the numbers.
// ============================================================================================

const CT_SEATS = ["red", "blue"];
const CT_KEYS = ["force", "build"];
const CT_TITLES: { [key: string]: string } = { force: "Force", build: "Build" };
const CT_TAG = "swtcg-counter";
const CT_SAVE_KEY = "swtcg-counters";
/** Hand-zone centre to the counter strip, toward the middle of the table (feet). */
const CT_STRIP = 0.4;
/** A control's centre from the seat's centreline, to the player's left (Force) or right (Build). */
const CT_SPREAD = 0.62;
/** A button's centre from its control's centre. */
const CT_BUTTON_GAP = 0.25;
const CT_CAP_WIDTH = 0.13;
const CT_CAP_HEIGHT = 0.04;
const CT_FRAME = 0.014;
const CT_MAX = 999;

/** "red:force" -> total. */
let ctValues: { [key: string]: number } = {};
let ctChain: Promise<void> = Promise.resolve();

function ctRun(fn: () => Promise<void>): Promise<void> {
  ctChain = ctChain.then(fn).catch((error) => {
    world.log("SWTCG counters: " + (error instanceof Error ? error.message : String(error)));
  });
  return ctChain;
}

/** A point in the seat's own frame: `right` toward the player's right, `ahead` toward the table's middle. */
function ctPoint(hand: SeatZoneInfo, right: number, ahead: number, lift: number): Vec3 {
  // A hand zone's local +x runs to its player's LEFT and local +z toward the middle of the table.
  const lx = -right;
  const r = (hand.rotationY * Math.PI) / 180;
  return [
    hand.position[0] + lx * Math.cos(r) + ahead * Math.sin(r),
    hand.position[1] + lift,
    hand.position[2] - lx * Math.sin(r) + ahead * Math.cos(r)
  ];
}

/** Yaw that reads upright for the seat's player. */
function ctReadYaw(hand: SeatZoneInfo): number {
  return (((hand.rotationY + 180) % 360) + 360) % 360;
}

async function ctHand(seat: string): Promise<SeatZoneInfo | null> {
  const zones = await world.getSeatZones(seat);
  return zones.find((z) => z.zoneType === "hand" && z.primary) || zones.find((z) => z.zoneType === "hand") || null;
}

function ctLabel(hand: SeatZoneInfo, seat: string, key: string): void {
  const side = key === "force" ? -1 : 1;
  world.setTextLabel({
    id: "swtcg-" + seat + "-" + key,
    text: CT_TITLES[key] + "\n" + String(ctValues[seat + ":" + key] || 0),
    position: ctPoint(hand, side * CT_SPREAD, CT_STRIP, 0.004),
    rotationY: ctReadYaw(hand),
    size: 0.075,
    color: "#ffffff",
    background: "#1d2330",
    bold: true
  });
}

async function ctSpawnButton(hand: SeatZoneInfo, seat: string, key: string, step: number): Promise<void> {
  const side = key === "force" ? -1 : 1;
  const outer = CT_CAP_WIDTH + CT_FRAME * 2;
  const button = await world.spawnObject({
    kind: "button",
    presetId: "button-round",
    name: CT_TITLES[key] + (step > 0 ? " +1" : " -1") + " (" + seat + ")",
    position: ctPoint(hand, side * CT_SPREAD + step * CT_BUTTON_GAP, CT_STRIP, (CT_CAP_HEIGHT + CT_FRAME) / 2),
    rotation: [0, ctReadYaw(hand), 0],
    scale: [outer, CT_CAP_HEIGHT + CT_FRAME, outer],
    tags: [CT_TAG],
    metadata: {
      standardPresetFamily: "props",
      standardPresetVariant: "button-round",
      swtcgCounter: { seat, key, step },
      button: {
        shape: "round",
        width: CT_CAP_WIDTH,
        height: CT_CAP_HEIGHT,
        travel: 0.015,
        frame: { enabled: true, thickness: CT_FRAME, height: CT_FRAME },
        colors: { cap: key === "force" ? "#3e8ede" : "#d9a531", text: "#ffffff" },
        face: { kind: "text", text: step > 0 ? "+" : "−", size: 0.95, bold: true },
        eventName: "swtcg-" + key + (step > 0 ? "-plus" : "-minus")
      }
    }
  });
  // A control, not a piece: a stray drag must not slide it off its spot (a spawned entity starts unlocked).
  if (button) button.lock();
}

async function ctLoad(): Promise<void> {
  ctValues = {};
  const raw = await world.getSavedData(CT_SAVE_KEY);
  if (!raw) return;
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== "object") return;
    for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
      if (typeof v === "number" && Number.isFinite(v)) ctValues[k] = Math.max(0, Math.min(CT_MAX, Math.round(v)));
    }
  } catch (error) {
    ctValues = {};
  }
}

async function ctSetup(): Promise<void> {
  await ctLoad();
  // Spawned buttons persist with the table, so a reload finds the last set: replace it rather than doubling it.
  for (const old of await world.getAllObjects({ tag: CT_TAG })) old.destroy();
  for (const seat of CT_SEATS) {
    const hand = await ctHand(seat);
    if (!hand) continue;
    for (const key of CT_KEYS) {
      ctLabel(hand, seat, key);
      await ctSpawnButton(hand, seat, key, -1);
      await ctSpawnButton(hand, seat, key, 1);
    }
  }
}

async function ctPressed(object: ObjectHandle): Promise<void> {
  const info = object.metadata.swtcgCounter as { seat?: unknown; key?: unknown; step?: unknown } | undefined;
  if (!info || typeof info.seat !== "string" || typeof info.key !== "string" || typeof info.step !== "number") return;
  if (CT_SEATS.indexOf(info.seat) < 0 || CT_KEYS.indexOf(info.key) < 0) return;
  const slot = info.seat + ":" + info.key;
  const next = Math.max(0, Math.min(CT_MAX, (ctValues[slot] || 0) + (info.step > 0 ? 1 : -1)));
  if (next === (ctValues[slot] || 0)) return;
  ctValues[slot] = next;
  await world.setSavedData(JSON.stringify(ctValues), CT_SAVE_KEY);
  const hand = await ctHand(info.seat);
  if (hand) ctLabel(hand, info.seat, info.key);
}

globalEvents.onObjectAction.add((object, action) => {
  if (action !== "press" || object.tags.indexOf(CT_TAG) < 0) return;
  void ctRun(() => ctPressed(object));
});

void ctRun(async () => {
  const variant = world.getVariant();
  if (variant.rulesEnforced) return;
  await ctSetup();
});

