    const r = (hand.rotationY * Math.PI) / 180;
    return [
        hand.position[0] + lx * Math.cos(r) + ahead * Math.sin(r),
        hand.position[1] + lift,
        hand.position[2] - lx * Math.sin(r) + ahead * Math.cos(r)
    ];
}
/** Yaw that reads upright for the seat's player. */
function ctReadYaw(hand) {
    return (((hand.rotationY + 180) % 360) + 360) % 360;
}
async function ctHand(seat) {
    const zones = await world.getSeatZones(seat);
    return zones.find((z) => z.zoneType === "hand" && z.primary) || zones.find((z) => z.zoneType === "hand") || null;
}
function ctLabel(hand, seat, key) {
    const side = key === "force" ? -1 : 1;
    world.setTextLabel({
        id: "swtcg-" + seat + "-" + key,
        text: CT_TITLES[key] + "\n" + String(ctValues[seat + ":" + key] || 0),
        position: ctPoint(hand, side * CT_SPREAD, CT_STRIP, 0.004),
        rotationY: ctReadYaw(hand),
        size: 0.075,
        color: "#ffffff",
        background: "#1d2330",
        bold: true
    });
}
async function ctSpawnButton(hand, seat, key, step) {
    const side = key === "force" ? -1 : 1;
    const outer = CT_CAP_WIDTH + CT_FRAME * 2;
    const button = await world.spawnObject({
        kind: "button",
        presetId: "button-round",
        name: CT_TITLES[key] + (step > 0 ? " +1" : " -1") + " (" + seat + ")",
        position: ctPoint(hand, side * CT_SPREAD + step * CT_BUTTON_GAP, CT_STRIP, (CT_CAP_HEIGHT + CT_FRAME) / 2),
        rotation: [0, ctReadYaw(hand), 0],
        scale: [outer, CT_CAP_HEIGHT + CT_FRAME, outer],
        tags: [CT_TAG],
        metadata: {
            standardPresetFamily: "props",
            standardPresetVariant: "button-round",
            swtcgCounter: { seat, key, step },
            button: {
                shape: "round",
                width: CT_CAP_WIDTH,
                height: CT_CAP_HEIGHT,
                travel: 0.015,
                frame: { enabled: true, thickness: CT_FRAME, height: CT_FRAME },
                colors: { cap: key === "force" ? "#3e8ede" : "#d9a531", text: "#ffffff" },
                face: { kind: "text", text: step > 0 ? "+" : "−", size: 0.95, bold: true },
                eventName: "swtcg-" + key + (step > 0 ? "-plus" : "-minus")
            }
        }
    });
    // A control, not a piece: a stray drag must not slide it off its spot (a spawned entity starts unlocked).
    if (button)
        button.lock();
}
async function ctLoad() {
    ctValues = {};
    const raw = await world.getSavedData(CT_SAVE_KEY);
    if (!raw)
        return;
    try {
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== "object")
            return;
        for (const [k, v] of Object.entries(parsed)) {
            if (typeof v === "number" && Number.isFinite(v))
                ctValues[k] = Math.max(0, Math.min(CT_MAX, Math.round(v)));
        }
    }
    catch (error) {
        ctValues = {};
    }
}
async function ctSetup() {
    await ctLoad();
    // Spawned buttons persist with the table, so a reload finds the last set: replace it rather than doubling it.
    for (const old of await world.getAllObjects({ tag: CT_TAG }))
        old.destroy();
    for (const seat of CT_SEATS) {
        const hand = await ctHand(seat);
        if (!hand)
            continue;
        for (const key of CT_KEYS) {
            ctLabel(hand, seat, key);
            await ctSpawnButton(hand, seat, key, -1);
            await ctSpawnButton(hand, seat, key, 1);
        }
    }
}
async function ctPressed(object) {
    const info = object.metadata.swtcgCounter;
    if (!info || typeof info.seat !== "string" || typeof info.key !== "string" || typeof info.step !== "number")
        return;
    if (CT_SEATS.indexOf(info.seat) < 0 || CT_KEYS.indexOf(info.key) < 0)
        return;
    const slot = info.seat + ":" + info.key;
    const next = Math.max(0, Math.min(CT_MAX, (ctValues[slot] || 0) + (info.step > 0 ? 1 : -1)));
    if (next === (ctValues[slot] || 0))
        return;
    ctValues[slot] = next;
    await world.setSavedData(JSON.stringify(ctValues), CT_SAVE_KEY);
    const hand = await ctHand(info.seat);
    if (hand)
        ctLabel(hand, info.seat, info.key);
}
globalEvents.onObjectAction.add((object, action) => {
    if (action !== "press" || object.tags.indexOf(CT_TAG) < 0)
        return;
    void ctRun(() => ctPressed(object));
});
void ctRun(async () => {
    const variant = world.getVariant();
    if (variant.rulesEnforced)
        return;
    await ctSetup();
});
